result.text:
        name: found.name,
        balance: found.balance || balancePorDefecto(key),
        pl: found.pl || "",
      }
    : {
        code: key,
        name: `Cuenta ${key}`,
        balance: balancePorDefecto(key),
        pl: "",
      };
  CACHE_CUENTAS.set(key, row);
  return row;
}

